const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

function formatarMoeda(valor) {
  return Number(valor).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  });
}

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// Captura os dados da entrada tratando o objeto 'body'
const inputData = $input.first().json;
const clientes = inputData.body?.clientes || inputData.clientes || [];
const investimentos = inputData.body?.investimentos || inputData.investimentos || [];

const resultados = clientes.map(c => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;

  const saldo_num = typeof c.saldo === 'number' 
    ? c.saldo 
    : Number(String(c.saldo).replace(/[^\d]/g, '')) || 0;
  const saldo_texto = formatarMoeda(saldo_num);

  const investimentosPerfil = investimentos.filter(inv => inv.perfil === perfil);

  let escolhido = investimentosPerfil.find(inv => saldo_num >= inv.minimo);
  let motivo = "saldo_ok";

  if (!escolhido && investimentosPerfil.length > 0) {
    escolhido = investimentosPerfil.reduce((prev, curr) => curr.minimo < prev.minimo ? curr : prev);
    motivo = "saldo_insuficiente";
  }

  const recomendacao = escolhido ? {
    perfil: escolhido.perfil,
    produto: escolhido.produto,
    minimo: escolhido.minimo,
    rentabilidade: escolhido.rentabilidade
  } : null;

  const minimo_texto = escolhido ? formatarMoeda(escolhido.minimo) : "R$ 0,00";
  const produto_nome = escolhido ? escolhido.produto : "Nenhum produto disponível";
  const rentabilidade = escolhido ? escolhido.rentabilidade : "";

  const mensagens = [
    `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${produto_nome}** (mínimo ${minimo_texto}). Com seu saldo atual (${saldo_texto}), você já consegue investir. Rentabilidade: ${rentabilidade}.`,
    `Oi ${nome}! Recomendações para perfil ${perfil}: **${produto_nome}** (mínimo ${minimo_texto}). Seu saldo (${saldo_texto}) já atende o mínimo. Rentabilidade: ${rentabilidade}.`,
    `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${produto_nome}** (mínimo ${minimo_texto}). Você tem ${saldo_texto}, então dá pra aplicar. Rentabilidade: ${rentabilidade}.`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto,
    saldo_num,
    recomendacao,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente no n8n
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

