return $input.all().map(item => {
  const j = item.json;

  // 1. Captura o e-mail (do nó atual ou via fallback do nó Code in JavaScript2)
  const to = j.email_to 
          || j.email 
          || $node["Code in JavaScript2"]?.json?.email_to 
          || "";

  // 2. Mapeia a estrutura exata do nó Message a model1 (Gemini)
  const rawText = j.content?.parts?.[0]?.text 
               || j.output?.[0]?.content?.[0]?.text 
               || j.message?.content 
               || j.text 
               || "";

  // 3. Limpa marcações markdown ```json ... ``` caso existam
  const cleanJsonText = rawText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/, "")
    .replace(/\s*```$/, "")
    .trim();

  let parsed = {};
  try {
    parsed = JSON.parse(cleanJsonText);
  } catch (e) {
    parsed = {
      subject: "Sugestão de Investimento",
      text_body: rawText,
      html_body: `<p>${rawText}</p>`
    };
  }

  return {
    json: {
      ok: true,
      to: to,
      subject: parsed.subject || "",
      text_body: parsed.text_body || "",
      html_body: parsed.html_body || "",

      meta: {
        nome: j.nome || $node["Code in JavaScript2"]?.json?.nome,
        perfil: j.perfil || $node["Code in JavaScript2"]?.json?.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});;
